import { useEffect, useState } from 'react';
import { supabase } from '../lib/supabase'; // Supabaseクライアントをインポート

// 型定義（ここに書く）
type Task = {
  id: number;
  name: string;
  completed: boolean;
};


const Home = () => {
  // useStateに型を指定
  
  const [tasks, setTasks] = useState<Task[]>([]);

  useEffect(() => {
    const fetchData = async () => {
      const { data, error } = await supabase
        .from('tasks') // Supabaseのテーブル名
        .select('id, name, completed'); // 必要なカラムを指定

      if (error) {
        console.error('Error fetching data:', error);
      } else {
        setTasks(data); // データをstateにセット
      }
    };

    fetchData();
  }, []);

  return (
    <div>
      {tasks.map((task) => (
        <div key={task.id}>
          <h2>{task.name}</h2>
          <p>{task.completed ? 'Done' : 'Not Done'}</p>
          <h1>神さ</h1>
        </div>
      ))}
    </div>
  );
};

export default Home;
